async function request(path, { method = 'GET', body, signal, token } = {}) {
  const response = await fetch(path, { method, credentials:'same-origin', signal, headers:{ ...(body ? {'Content-Type':'application/json'} : {}), ...(token ? {'X-Demo-Session':token} : {}) }, ...(body ? {body:JSON.stringify(body)} : {}) });
  let data; try { data = await response.json(); } catch { throw new Error('Máy chủ chưa sẵn sàng. Hãy kiểm tra dịch vụ API.'); }
  if (!response.ok) { const error = new Error(data.error?.message || data.message || (typeof data.error === 'string' ? data.error : 'Không thể thực hiện thao tác.')); Object.assign(error, {status:response.status,code:data.code||data.error?.code}); throw error; }
  return data;
}

export function WorkflowProvider({ role, children, onSnapshot }) {
  const [snapshot, setSnapshot] = useState(null), [status, setStatus] = useState('loading'), [error,setError] = useState(''), [busy,setBusy] = useState(false), [aiStatus,setAIStatus] = useState(null);
  const roleRef = useRef(role), epoch = useRef(0), token = useRef(''), pending = useRef(0), snapshotCallback = useRef(onSnapshot), sessionQueue = useRef(Promise.resolve()), abort = useRef(null);
  roleRef.current = role; snapshotCallback.current = onSnapshot;
  function receive(data, run) {
    const next = data?.snapshot || data;
    if (run !== epoch.current || next?.user?.role !== roleRef.current) return null;
    setSnapshot(next); setStatus('ready'); snapshotCallback.current?.(next); return next;
  }
  async function refresh() {
    const run = epoch.current;
    try { await sessionQueue.current; if (run !== epoch.current) return null; if (!token.current) { const session = await request('/api/demo/session', {method:'POST',body:{role:roleRef.current}}); setError(''); if (run !== epoch.current) return null; token.current = session.sessionToken || session.token || ''; const ai = await request('/api/ai/status',{token:token.current}); if(run === epoch.current)setAIStatus(ai); } const data = await request('/api/workflow',{token:token.current}); return receive(data,run); }
    catch(reason) { if(run===epoch.current) {if(reason.status===401)token.current='';setError(reason.message);setStatus(current=>current==='loading'?'error':current);} return null; }
  }
  useEffect(() => {
    const run = ++epoch.current; token.current=''; setSnapshot(null); setError(''); setStatus('loading');setAIStatus(null);
    abort.current?.abort(); const controller = new AbortController(); abort.current = controller;
    // Serialize role changes so a late session response cannot restore the prior role.
    sessionQueue.current = sessionQueue.current.catch(()=>{}).then(async()=>{
      if(run!==epoch.current) return;
      const session=await request('/api/demo/session',{method:'POST',body:{role},signal:controller.signal});
      if(run!==epoch.current)return;
      token.current=session.sessionToken||session.token||'';
      const [data,ai]=await Promise.all([request('/api/workflow',{token:token.current,signal:controller.signal}),request('/api/ai/status',{token:token.current,signal:controller.signal})]);
      receive(data,run); if(run===epoch.current)setAIStatus(ai);
    }).catch(reason=>{if(run===epoch.current&&reason.name!=='AbortError'){setError(reason.message);setStatus('error');}});
    const interval=setInterval(()=>{if(!pending.current && run===epoch.current)refresh();},4000);
    return()=>{controller.abort();clearInterval(interval);};
  },[role]);
  async function perform(path,body) {
    const run=epoch.current;setError('');pending.current++;setBusy(true);
    try {await sessionQueue.current;if(run!==epoch.current)return null;const data=await request(path,{method:'POST',body,token:token.current});if(run!==epoch.current)return null;receive(data.snapshot||data,run);return data;}
    catch(reason){if(run===epoch.current){setError(reason.message);await refresh();}return null;}
    finally{pending.current--;if(!pending.current)setBusy(false);}
  }
  const api=async(path,options={})=>{await sessionQueue.current;return request(path,{...options,token:token.current});};
  const value={snapshot:snapshot?.user?.role===role?snapshot:null,sessionRole:snapshot?.user?.role||null,status,error,busy,aiStatus,refresh,api,clearError:()=>setError(''),action:body=>perform('/api/workflow/actions',body),runAnalysis:body=>perform('/api/ai/analysis',body)};
  return <WorkflowContext.Provider value={value}>{children}</WorkflowContext.Provider>;
}
export function useWorkflow(){const value=useContext(WorkflowContext);if(!value)throw new Error('InvestmentFlow cần WorkflowProvider.');return value;}

function Button({children,variant='primary',className='',...props}){return <button type="button" className={`inline-flex min-h-10 items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition disabled:cursor-not-allowed disabled:opacity-50 ${variant==='primary'?'bg-indigo-600 text-white hover:bg-indigo-700':variant==='danger'?'border border-rose-100 bg-rose-50 text-rose-700':'border border-slate-200 bg-white text-slate-700 hover:bg-slate-100'} ${className}`} {...props}>{children}</button>;}
function Card({children,className=''}){return <section className={`min-w-0 rounded-2xl border border-slate-200 bg-white p-5 sm:p-6 ${className}`}>{children}</section>;}
function Field({label,children,hint}){return <div className="space-y-2"><label className="block space-y-2 text-sm font-medium text-slate-700"><span>{label}</span>{children}</label>{hint&&<p className="text-xs font-normal leading-5 text-slate-500">{hint}</p>}</div>;}
function Heading({title,description,action}){return <div className="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div className="min-w-0"><p className="mb-2 text-xs font-semibold uppercase tracking-widest text-indigo-500">2G2BT · Kết nối đầu tư</p><h1 className="text-2xl font-bold tracking-tight text-slate-900 sm:text-3xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">{description}</p></div>{action&&<div className="shrink-0">{action}</div>}</div>;}
function Empty({title,children}){return <div className="rounded-xl border border-dashed border-slate-200 px-5 py-10 text-center"><FolderOpen className="mx-auto mb-3 text-indigo-400" size={28}/><h3 className="font-semibold text-slate-700">{title}</h3><div className="mx-auto mt-2 max-w-md text-sm leading-6 text-slate-500">{children}</div></div>;}
function Badge({status,payments}){const granted=status==='approved'&&payments?.startup&&payments?.investor;return <span className={`inline-flex rounded-full px-2.5 py-1 text-xs font-medium ${granted?'bg-teal-50 text-teal-600':status==='rejected'||status==='revoked'?'bg-rose-50 text-rose-700':'bg-amber-50 text-amber-700'}`}>{granted?'Đã cấp quyền':statusLabels[status]||status}</span>;}
function AccountIdentity(){const {snapshot}=useWorkflow();return <div className="mb-5 flex flex-wrap items-center justify-between gap-2 rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-xs leading-5 text-slate-500"><span>Tài khoản: <strong className="text-slate-700">{snapshot.user.name}</strong></span><span>Dữ liệu lưu trên máy chủ</span></div>;}
function Budget(){const {snapshot,aiStatus}=useWorkflow();const q=snapshot.usage;return <Card><div className="flex flex-wrap items-center justify-between gap-3"><h2 className="font-semibold text-slate-900">Ngân sách AI</h2><span className="rounded-full bg-indigo-50 px-3 py-1 text-xs font-semibold text-indigo-700">{snapshot.user.role==='founder'?'Hạn mức hiện tại':snapshot.plan.name}</span></div><p className="mt-4 text-3xl font-bold text-slate-900">{money(q.remaining)} <small className="text-sm font-normal text-slate-500">token còn lại</small></p><div className="my-3 h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-indigo-500" style={{width:`${Math.min(100,q.used/q.limit*100)}%`}}/></div><p className="text-xs text-slate-500">{money(q.used)} / {money(q.limit)} token đã dùng hoặc tạm giữ · {q.period==='lifetime'?'Free cấp một lần':'Cấp lại mỗi thứ Hai'}</p>{q.pendingTokens>0&&<p className="mt-2 text-xs text-amber-700">Đang tạm giữ {money(q.pendingTokens)} token cho {q.pendingAnalyses} lần phân tích chờ đối soát.</p>}{q.resetAt&&<p className="mt-2 text-xs text-slate-500">Reset: {dateLabel(q.resetAt)} · giờ Việt Nam</p>}<p className="mt-3 text-xs leading-5 text-slate-500">{aiStatus?.configured?`${aiStatus.provider||'API'} · ${aiStatus.model}`:'Phân tích AI hiện chưa khả dụng.'}</p><a href="#/pricing" className="mt-3 inline-block text-sm font-semibold text-indigo-600">{snapshot.user.role==='founder'?'Xem phí theo case':'Quản lý gói'} →</a></Card>;}

export function InvestmentFlow({view='workspace',id=''}){
  const {snapshot,status,error,refresh,clearError}=useWorkflow();
  if(!snapshot)return <Card><h1 className="text-xl font-bold">{status==='error'?'Chưa kết nối được máy chủ':'Đang tải không gian đầu tư…'}</h1><p className="my-4 text-sm text-slate-500">{error||'Đang kiểm tra tài khoản và quyền truy cập của bạn.'}</p>{status==='error'&&<Button onClick={refresh}><RefreshCw size={16}/>Thử lại</Button>}</Card>;
  return <div className="mx-auto max-w-[1350px]"><AccountIdentity/>{error&&<div role="alert" className="mb-5 flex items-start justify-between gap-3 rounded-xl border border-rose-100 bg-rose-50 p-4 text-sm leading-6 text-rose-700"><span>{error}</span><button aria-label="Đóng thông báo lỗi" onClick={clearError}><X size={17}/></button></div>}{view==='marketplace'?(snapshot.user.role==='founder'?<FounderProjects/>:<Marketplace/>):view==='detail'?<ProjectDetail id={id}/>:view==='portfolio'?<Portfolio/>:view==='analysis'?<Analysis id={id}/>:<Workspaces id={id}/>}</div>;
}

